// Requires a boot entry that sets the stack and clears .bss.
// No hosted runtime, exceptions, RTTI or static constructors.
extern "C" [[noreturn]] void kernel_main() {
    for (;;) {
        __asm__ volatile ("cli; hlt" : : : "memory");
    }
}

