// Pair with the matching ARM startup and linker script.
// Interrupts remain masked; initialize vectors/hardware before enabling them.
extern "C" [[noreturn]] void kernel_main() {
    for (;;) {
        __asm__ volatile ("wfi" : : : "memory");
    }
}
